"use client";

import Link from "next/link";
import { DeployStage } from "./DeployStage";

/* ------------------------------------------------------------------ */
/*  Hero shell with animated background (Website Overhaul v2)           */
/*                                                                     */
/*  Ships the approved /v9 hero: a product-and-audience headline       */
/*  ("Everything you build, online in 60 seconds") plus the friendly,  */
/*  non-terminal <DeployStage/> visual — plain-language deploy steps    */
/*  that resolve to a live-server card, instead of a shell session that */
/*  read as developer-only. The animated background shell is retained.  */
/*                                                                     */
/*  Note: the /v9 preview also carried third-party <ReviewBadges/> and  */
/*  a "30-day money-back" chip. Both are deliberately omitted here —    */
/*  the badge scores are placeholders (fabricated endorsement on an     */
/*  indexable page) and no money-back guarantee exists on the site.     */
