602	/* -------------------------------------------------------------------------- */
603	/* Deliverability self-check                                                   */
604	/* -------------------------------------------------------------------------- */
605	
606	const CHECK_TONE: Record<CheckStatus, "green" | "amber" | "red" | "slate"> = {
607	  pass: "green",
608	  warn: "amber",
609	  fail: "red",
610	  unknown: "slate",
611	};
612	
613	const CHECK_LABEL: Record<CheckStatus, string> = {
614	  pass: "Pass",
615	  warn: "Warning",
616	  fail: "Fail",
617	  unknown: "Unknown",
618	};
619	
620	/**
621	 * Per-domain SPF / DKIM / DMARC / MX self-check.
622	 *
623	 * WHY: "my mail goes to spam" was undiagnosable from inside the product. The
624	 * platform owner hit exactly this and had to diagnose it with an external
625	 * third-party tool, so every customer in the same position had no route at all.
626	 *
627	 * Two things this panel must never do, because both would make it the codebase's
628	 * recurring defect in a new place — a surface reporting an outcome it never
629	 * verified, here telling someone their mail is fine while it goes to spam:
630	 *
631	 *   1. Report a status the server did not derive from DNS. Every badge below
632	 *      comes from `checkEmailDeliverability`, which reads the zone's own
633	 *      AUTHORITATIVE nameservers (this host's `hosts: files myhostname dns`
634	 *      nsswitch order can answer a lookup out of /etc/hosts while looking like a
635	 *      real query — that produced one confidently wrong diagnosis already).
636	 *   2. Round a partial answer up. `unknown` renders as its own slate state, not
637	 *      as a pass, and the nameservers actually queried are printed so the result
638	 *      is auditable rather than taken on trust.
639	 *
640	 * Not auto-run: each check is several outbound DNS queries plus one Mailcow call,
641	 * and the customer has to be looking at it for the answer to be useful.
642	 */
643	function DeliverabilityPanel({
644	  subscriptionId,
645	  domainName,
646	}: {
647	  subscriptionId: string;
648	  domainName: string;
649	}) {
650	  const [report, setReport] = useState<DeliverabilityReport | null>(null);
651	  const [error, setError] = useState<string | null>(null);
652	  const [pending, start] = useTransition();
653	
654	  function run() {
655	    setError(null);
656	    start(async () => {
657	      const res = await checkEmailDeliverability(subscriptionId);
658	      if (res?.error) {
659	        setError(res.error);
660	        setReport(null);
661	      } else if (res?.report) {
662	        setReport(res.report);
663	      }
664	    });
665	  }
666	
667	  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
668	  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
669	  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;
670	
671	  return (
672	    <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
673	      <div className="flex flex-wrap items-center justify-between gap-2">
674	        <div className="flex flex-wrap items-center gap-2">
675	          <span className="text-sm font-semibold text-white">Deliverability check</span>
676	          {report &&
677	            (failing > 0 ? (
678	              <Badge tone="red">
679	                {failing} problem{failing === 1 ? "" : "s"}
680	              </Badge>
681	            ) : unknown > 0 ? (
682	              <Badge tone="slate">Incomplete</Badge>
683	            ) : warning > 0 ? (
684	              <Badge tone="amber">
685	                {warning} warning{warning === 1 ? "" : "s"}
686	              </Badge>
687	            ) : (
688	              <Badge tone="green">All checks pass</Badge>
689	            ))}
690	        </div>
691	        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
692	          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
693	        </button>
694	      </div>
695	
696	      <p className="mt-2 text-xs text-slate-400">
697	        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
698	        and DMARC. If your mail is landing in spam, a failing row here is usually why.
699	      </p>
700	
701	      {error && (
702	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
703	          {error}
704	        </div>
705	      )}
706	
707	      {report && (
708	        <div className="mt-3 space-y-2">
709	          {report.error && (
710	            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
711	              {report.error}
712	            </div>
713	          )}
714	
715	          {report.checks.map((c) => (
716	            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
717	              <div className="flex flex-wrap items-center gap-2">
718	                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
719	                <span className="text-sm font-medium text-slate-200">{c.label}</span>
720	                <span className="text-[11px] text-slate-500">
721	                  {c.type} · <span className="font-mono">{c.host}</span>
722	                </span>
723	              </div>
724	
725	              <div className="mt-2 grid gap-2 sm:grid-cols-2">
726	                <div className="min-w-0">
727	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
728	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
729	                    {c.observed || "— nothing published —"}
730	                  </code>
731	                </div>
732	                <div className="min-w-0">
733	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
734	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
735	                    {c.expected || "—"}
736	                  </code>
737	                </div>
738	              </div>
739	
740	              <p
741	                className={`mt-2 text-xs ${
742	                  c.status === "fail"
743	                    ? "text-red-400"
744	                    : c.status === "warn"
745	                      ? "text-amber-400"
746	                      : c.status === "pass"
747	                        ? "text-emerald-300/80"
748	                        : "text-slate-400"
749	                }`}
750	              >
751	                {c.detail}
752	              </p>
753	            </div>
754	          ))}
755	
756	          {/* Printing the nameservers is the point, not decoration: it is how the
757	              customer (or support) can tell this answer came from the zone's own
758	              authority and not from a stale recursive cache. */}
759	          <p className="text-[11px] text-slate-500">
760	            {report.nameservers.length > 0 ? (
761	              <>
762	                Read directly from this domain&apos;s nameservers (
763	                <span className="font-mono">{report.nameservers.join(", ")}</span>), so a record you
764	                just changed shows up straight away.
765	              </>
766	            ) : (
767	              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
768	            )}{" "}
769	            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
770	          </p>
771	        </div>
772	      )}
773	    </div>
774	  );
775	}
