/**
 * Wizard-wide reassurance strip — shown on EVERY step of every deploy wizard
 * (the product-selection landing screen through Review), not just the payment
 * point. Distinct from `PaymentTrustBar` (components/customer/PaymentTrustBar.tsx),
 * which is a payment-METHOD-specific row (card network marks + "Secured by
 * Stripe") shown only on the Review step right before checkout — that one keeps
 * its job unchanged. This one is the general "you're in good hands" signal that
 * should follow the customer through the whole flow, so it renders unconditionally
 * near the bottom of every step's card, not gated on `isLast`.
 *
 * HONESTY, same rule PaymentTrustBar already documents: every claim shown here
 * must be one already made truthfully elsewhere on the site — never an invented
 * one. A "money-back guarantee" chip was investigated for this build and is
 * deliberately NOT enabled for any product today:
 *
 *   - Three separate prior-pass comments (app/page.tsx's hero, components/
 *     marketing/AnimatedHero.tsx, components/marketing/ProductPricing.tsx) record
 *     that a "30-day money-back guarantee" claim was reviewed and REMOVED sitewide
 *     because no such guarantee is actually published or honoured.
 *   - lib/kb-system.ts's support-chat knowledge base explicitly instructs: "There
 *     is no separately published 'N-day money-back guarantee' figure in this KB,
 *     so don't promise a specific window."
 *   - The only surviving "30-day money-back guarantee" string in the repo
 *     (components/marketing/RocketPricing.tsx) sits on a component nothing else
 *     imports — dead marketing copy, not a live policy.
 *   - No current wizard (VPS/Hosting/Game) renders a money-back claim at all —
 *     grepped for "Guarantee", "Money Back", "3-Day", "30-Day" across app/ and
 *     components/ and found nothing in any live wizard step.
 *
 * So `moneyBackDays` exists here, ready for a REAL, admin-confirmed policy per
 * product, but no caller passes one today. Do not wire one up without a verified
 * source of truth — see the deploy-wizard-unification report for the full trail.
 */
export function WizardTrustBar({
  className = "",
  moneyBackDays,
}: {
  className?: string;
  /** Only pass this once a product's money-back window is a real, published,
   *  charge-honoured policy — see the HONESTY note above. Omitted everywhere
   *  today because no such policy currently exists for any product. */
  moneyBackDays?: number;
}) {
  const claims = [
    "99.9% uptime SLA",
    "24/7 expert support",
    "Instant setup",
    ...(moneyBackDays ? [`${moneyBackDays}-day money-back guarantee`] : []),
  ];
  return (
    <div className={`flex flex-wrap gap-x-5 gap-y-1.5 text-xs text-slate-400 ${className}`}>
      {claims.map((c) => (
        <span key={c} className="flex items-center gap-1.5">
          <span className="text-emerald-400">✓</span>
          {c}
        </span>
      ))}
    </div>
  );
}

