        return (
          <button
            type="button"
            key={t.months}
            onClick={() => setTermMonths(t.months)}
            className={`card relative px-3 py-2.5 text-left transition ${
              on ? "!border-brand-400 ring-1 ring-brand-400" : disc > 0 ? "hover:!border-emerald-400/50" : "hover:border-white/20"
