            {isLongest && disc > 0 && (
              <span className="absolute -top-2 right-2 rounded-full bg-gradient-to-r from-emerald-500 to-teal-500 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider text-white shadow">
                Best value
              </span>
