            <div className="text-sm font-semibold">{t.label}</div>
            <div className={`text-[11px] font-medium ${disc > 0 ? "text-emerald-300" : "text-slate-400"}`}>
              {disc > 0 ? `Save ${disc}%` : "Flexible — cancel anytime"}
            </div>
          </button>
        );
      })}
    </div>
    <h2 className="mb-4 font-semibold">Choose your resources</h2>
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
      {plans.map((p, i) => {
