const PASSWORD = "WizardQA12345test";

async function main() {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const page = await ctx.newPage();

  // Register a throwaway QA account (idempotent-ish: if it already exists, fall back to login).
  await page.goto(`${BASE}/register`, { waitUntil: "networkidle" });
  const hasNameField = await page.locator('input[name="name"]').count();
  if (hasNameField) {
    await page.fill('input[name="name"]', "Wizard QA");
    await page.fill('input[name="email"]', EMAIL);
    await page.fill('input[name="password"]', PASSWORD);
    await page.click('button:has-text("Create account")');
    await page.waitForLoadState("networkidle").catch(() => {});
  }
  // If registration failed because the account exists, log in instead.
  if (page.url().includes("/register") || page.url().includes("/login")) {
    await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
    await page.fill('input[name="email"]', EMAIL);
    await page.fill('input[name="password"]', PASSWORD);
    await page.click('button[type="submit"], button:has-text("Sign in"), button:has-text("Log in")');
    await page.waitForLoadState("networkidle").catch(() => {});
  }

  await ctx.storageState({ path: "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/qa-storage.json" });

  // ---- VPS (default active tab) ----
  await page.goto(`${BASE}/dashboard/deploy?product=vps`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/before-vps-plan.png`, fullPage: true });

  // ---- Shared Hosting ----
  await page.goto(`${BASE}/dashboard/deploy?product=hosting`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/before-hosting-plan.png`, fullPage: true });

  // ---- Game Servers ----
  await page.goto(`${BASE}/dashboard/deploy?product=game`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/before-game-gamepicker.png`, fullPage: true });
  // Click first game tile to reach the Plan step.
  const gameTile = page.locator('button[aria-pressed]').first();
  if (await gameTile.count()) {
    await gameTile.click();
    await page.waitForTimeout(800);
    await page.screenshot({ path: `${OUT}/before-game-plan.png`, fullPage: true });
  }

  // ---- Business Email ----
  await page.goto(`${BASE}/dashboard/deploy?product=email`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/before-email-panel.png`, fullPage: true });

  await browser.close();
  console.log("DONE");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

