import { chromium } from "playwright";

const BASE = "http://localhost:3777";
const OUT = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/wizard-shots";
const STORAGE = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/qa-storage.json";

async function dismissOverlays(page) {
  for (const text of ["Skip", "Got it"]) {
    const btn = page.locator(`button:has-text("${text}")`).first();
    if (await btn.count()) {
      try {
        await btn.click({ timeout: 1500 });
        await page.waitForTimeout(250);
      } catch {}
    }
  }
}

async function clickContinueIfEnabled(page) {
  const btn = page.locator('button:has-text("Continue")').first();
  if (!(await btn.count())) return false;
  const disabled = await btn.getAttribute("disabled");
  if (disabled !== null) return false;
  await btn.click();
  await page.waitForTimeout(600);
  return true;
}

async function main() {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1100 }, storageState: STORAGE });
  const page = await ctx.newPage();

  // ---- VPS ----
  await page.goto(`${BASE}/dashboard/deploy?product=vps`, { waitUntil: "networkidle" });
  await page.waitForTimeout(900);
  await dismissOverlays(page);
  await page.screenshot({ path: `${OUT}/after-vps-plan.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Install
  await page.screenshot({ path: `${OUT}/after-vps-install.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Add-ons
  await clickContinueIfEnabled(page); // -> Access
  await page.screenshot({ path: `${OUT}/after-vps-access.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Review
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/after-vps-review.png`, fullPage: true });

  // ---- Shared Hosting ----
  await page.goto(`${BASE}/dashboard/deploy?product=hosting`, { waitUntil: "networkidle" });
  await page.waitForTimeout(900);
  await dismissOverlays(page);
  await page.screenshot({ path: `${OUT}/after-hosting-plan.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Domain
  await page.screenshot({ path: `${OUT}/after-hosting-domain.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Install (if apps) or Add-ons
  await clickContinueIfEnabled(page); // -> Add-ons or Review
  await clickContinueIfEnabled(page); // -> Review (in case Install existed)
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/after-hosting-review.png`, fullPage: true });

  // ---- Game Servers ----
  await page.goto(`${BASE}/dashboard/deploy?product=game`, { waitUntil: "networkidle" });
  await page.waitForTimeout(900);
  await dismissOverlays(page);
  await page.screenshot({ path: `${OUT}/after-game-gamepicker.png`, fullPage: true });
  const gameTile = page.locator("div.grid button[aria-pressed]").first();
  if (await gameTile.count()) {
    await gameTile.click();
    await page.waitForTimeout(600);
  }
  await page.screenshot({ path: `${OUT}/after-game-plan.png`, fullPage: true });
  // Pick the first tier card so Continue enables.
  const tierCard = page.locator('button.card').first();
  if (await tierCard.count()) {
    await tierCard.click();
    await page.waitForTimeout(400);
  }
  await page.screenshot({ path: `${OUT}/after-game-plan-selected.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Settings
  await page.screenshot({ path: `${OUT}/after-game-settings.png`, fullPage: true });
  await clickContinueIfEnabled(page); // -> Review
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/after-game-review.png`, fullPage: true });

  // ---- Business Email ----
  await page.goto(`${BASE}/dashboard/deploy?product=email`, { waitUntil: "networkidle" });
  await page.waitForTimeout(900);
  await dismissOverlays(page);
  await page.screenshot({ path: `${OUT}/after-email-panel.png`, fullPage: true });

  await browser.close();
  console.log("DONE");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
